import {flushPromises,mount} from '@vue/test-utils'
import {createI18n} from 'vue-i18n'
import {createMemoryHistory,createRouter,RouterView} from 'vue-router'
import zhTW from '../../locales/zh-TW.json'
import Workbench from '../src/views/WorkbenchView.vue'
import EvidenceInspector from '../src/components/EvidenceInspector.vue'
import RunReplay from '../src/components/RunReplay.vue'
import ReportVersionAction from '../src/components/ReportVersionAction.vue'
