const source={source_id:'src1',project_id:'p',title:'來源一',source_type:'document',identity:'file.txt'}
const text='😀甲乙 <script>alert(1)</script>'
const version={version_id:'v1',source_id:'src1',content:text,content_available:true,character_count:Array.from(text).length,created_at:'2026-01-01',sha256:'fixture-hash',spans:{items:[],total:0}}
const page=items=>({items,total:items.length,has_more:false})
const project={project_id:'p',name:'測試研究',simulation_requirement:'測試问题',status:'created',archived:false}
const runs=[{simulation_id:'s1',run_id:'run1',status:'completed',graph_ready:false,manifest:{kind:'synthetic_fixture'}},{simulation_id:'s2',run_id:'run2',status:'completed',graph_ready:true,manifest:{}},{simulation_id:'stopped',run_id:'run3',status:'stopped'}]
const event=(seq=1)=>({event_id:`e${seq}`,run_id:'run1',attempt_id:'attempt',seq,platform:'twitter',agent_id:'0',round:seq,kind:'POST',content:`saved ${seq}`,observed_at:'2026-01-01'})
let calls,overrides,wrappers,originalAdapter,detail
function response(config,data) {return {config,status:200,statusText:'OK',headers:{},data:{success:true,data}}}
function failed(message='保存失敗',status=400) {throw Object.assign(new Error(message),{isAxiosError:true,response:{status,data:{error:message}}})}
const writes=()=>calls.filter(c=>['post','patch','delete'].includes(c.method))
const requests=path=>calls.filter(c=>c.url===`/api/workbench${path}`)
const deferred=()=>{let resolve;const promise=new Promise(r=>{resolve=r});return {promise,resolve}}
const body=c=>typeof c.data==='string'?JSON.parse(c.data):c.data
function button(wrapper,label){const found=wrapper.findAll('button').find(b=>b.text()===label);if(!found)throw new Error(`Missing button: ${label}`);return found}
async function tick(){await flushPromises();await flushPromises()}
beforeEach(()=>{
  sessionStorage.clear();calls=[];overrides=new Map();wrappers=[];api.resetWorkbenchSession();originalAdapter=api.workbenchClient.defaults.adapter
  detail={project:{...project},sources:page([source]),references:page([]),runs:[...runs],reports:[{report_id:'r',simulation_id:'s1',status:'completed',markdown_content:'已保存報告 <script>report()</script>',manifest:{kind:'synthetic_fixture'}}]}
  api.workbenchClient.defaults.adapter=async config=>{
    calls.push(config)
    if(overrides.has(config.url))return response(config,await overrides.get(config.url)(config))
    const path=config.url.replace('/api/workbench','')
    if(path==='/session')return response(config,{csrf_token:'fixture-session-token'})
    if(path==='/projects'&&config.method==='get')return response(config,page([{...project}]))
    if(path==='/projects'&&config.method==='post')return response(config,{...project,project_id:'new-draft'})
    if(/^\/projects\/[^/]+$/.test(path)&&config.method==='get')return response(config,{...detail,project:{...detail.project,project_id:path.split('/').at(-1)}})
    if(/^\/projects\/[^/]+$/.test(path)&&config.method==='patch')return response(config,{...project,...body(config)})
    if(path.endsWith('/quality'))return response(config,{source_preservation:{numerator:0,denominator:0,value:null,definition:'保存原文 / 所有版本'},citation_location:{numerator:0,denominator:0,value:null,definition:'可定位 / 来源引用'},run_counts:{total:3,completed:2,incomplete:1},assumptions:[],contradictions:[],limitations:['定位不等於內容正確。']})
    if(path.endsWith('/clone'))return response(config,{project_id:'copy'})
    if(path.endsWith('/legacy-index'))return response(config,{sources:[]})
    if(path.endsWith('/sources')&&config.method==='get')return response(config,page([source]))
    if(path.endsWith('/sources')&&config.method==='post')return response(config,{source,version})
    if(path.endsWith('/references')&&config.method==='get')return response(config,page([]))
    if(path.endsWith('/references')&&config.method==='post')return response(config,{reference_id:'ref1',...body(config)})
    if(path.startsWith('/sources/'))return response(config,{source,versions:page([version])})
    if(path.endsWith('/spans'))return response(config,{span_id:'span1',...body(config)})
    if(path.startsWith('/versions/'))return response(config,version)
    if(path==='/tasks')return response(config,{items:[{task_id:'task1',status:'interrupted',description:'保存中的任務'}],runs:[runs[2]]})
    if(path==='/demos')return response(config,page([{id:'product',title:'產品示範',description:'合成內容',kind:'synthetic_fixture'}]))
    if(path==='/demos/product')return response(config,{project_id:'demo'})
    if(path.endsWith('/events'))return response(config,{items:[event()],next_cursor:'cursor1',has_more:false,capability:'exact_event_projection',limitations:[],cost:{status:'unknown',value:null}})
    if(path.endsWith('/projection'))return response(config,{through_seq:config.params.through_seq,events:config.params.through_seq?[event()]:[],actors:[],relationships:[],capability:'exact_event_projection',limitations:[]})
    if(path==='/compare')return response(config,{non_single_variable:true,causal_claim:false,manifest_diff:[{path:'model',left:'a',right:'b',left_present:true,right_present:true}],kind_counts:{left:{twitter:{POST:1}},right:{reddit:{POST:2}}},first_difference:{index:1,left:event(),right:{...event(),content:'different'}},limitations:['未確認因果。']})
    throw new Error(`Unexpected fixture request: ${config.method} ${path}`)
  }
})
afterEach(()=>{wrappers.forEach(w=>w.unmount());api.workbenchClient.defaults.adapter=originalAdapter;document.body.innerHTML='';vi.clearAllTimers();vi.useRealTimers();vi.restoreAllMocks()})
async function render(component=Workbench,props={},path='/workbench/p?section=data') {
 const router=createRouter({history:createMemoryHistory(),routes:[{path:'/workbench/:projectId?',name:'Workbench',component:Workbench,props:true},{path:'/report/:reportId',name:'Report',component:{template:'<div />'}},{path:'/settings',name:'Settings',component:{template:'<div />'}},{path:'/:pathMatch(.*)*',component:{template:'<div />'}}]})
 await router.push(path);await router.isReady()
 const wrapper=mount(component===Workbench?RouterView:component,{props,attachTo:document.body,global:{plugins:[router,createI18n({legacy:false,locale:'zh-TW',messages:{'zh-TW':zhTW}})],stubs:{LanguageSwitcher:true}}})
 wrappers.push(wrapper);await tick();return {wrapper,router}
}

describe('home research overview',()=>{
 it('shows only active saved work with a task-center link and no invented percentages',async()=>{overrides.set('/api/workbench/tasks',()=>({items:[{task_id:'working',status:'processing',description:'處理中工作',progress:0},{task_id:'done',status:'completed',description:'完成工作'}],runs:[{run_id:'r',simulation_id:'active-run',status:'stopping'},{run_id:'old',simulation_id:'old-run',status:'interrupted'}]}));const {wrapper}=await render(HomeResearchOverview);const summary=wrapper.get('.active-work-summary');expect(summary.text()).toContain('處理中工作');expect(summary.text()).toContain('active-run');expect(summary.text()).not.toContain('完成工作');expect(summary.text()).not.toContain('old-run');expect(summary.text()).not.toContain('%');expect(summary.find('progress').exists()).toBe(false);expect(summary.find('a[href="/workbench?view=tasks"]').exists()).toBe(true);expect(writes()).toHaveLength(0)})
 it('retries a failed task read and hides the summary when no active work remains',async()=>{overrides.set('/api/workbench/tasks',()=>failed('任務無法讀取'));const {wrapper}=await render(HomeResearchOverview);expect(wrapper.get('.active-work-summary').text()).toContain('任務無法讀取');overrides.set('/api/workbench/tasks',()=>({items:[],runs:[]}));await wrapper.get('.active-work-summary button').trigger('click');await tick();expect(wrapper.find('.active-work-summary').exists()).toBe(false);expect(requests('/tasks')).toHaveLength(2);expect(writes()).toHaveLength(0)})
 it.each([['stopped','已停止'],['failed','失敗'],['completed','已完成'],[undefined,'狀態未知']])('preserves a saved report while showing its actual %s run state',async(runState,label)=>{const saved={report_id:'old-report',report_status:'completed',runner_status:runState,simulation_requirement:'歷史結果'};const {wrapper}=await render(HomeResearchOverview,{historyState:{loading:false,error:false,items:[saved]}});const link=wrapper.get('a[href="/report/old-report"]');expect(link.text()).toContain('已保存的報告');expect(link.text()).toContain(`執行：${label}`);expect(link.text()).not.toContain('完整報告');expect(saved.report_status).toBe('completed');expect(saved.runner_status).toBe(runState);expect(writes()).toHaveLength(0)})
 it('reads a small recent project list, reuses completed history and keeps demos as navigation',async()=>{const {wrapper}=await render(HomeResearchOverview,{historyState:{loading:false,error:false,items:[{report_id:'complete',report_status:'completed',simulation_requirement:'保存成果'},{report_id:'incomplete',report_status:'interrupted'}]}});expect(calls.map(call=>call.url).sort()).toEqual(['/api/workbench/projects','/api/workbench/tasks']);expect(requests('/projects')[0].params).toEqual({archived:0,offset:0,limit:4});expect(wrapper.get('a[href="/workbench/p"]').text()).toContain('測試研究');expect(wrapper.find('a[href="/report/complete"]').exists()).toBe(true);expect(wrapper.find('a[href="/report/incomplete"]').exists()).toBe(false);expect(wrapper.find('a[href="/workbench?view=demos"]').exists()).toBe(true);expect(writes()).toHaveLength(0)})
 it('offers a retry after a failed recent-project read and preserves the history shortcut',async()=>{overrides.set('/api/workbench/projects',()=>failed('讀取失敗'));const {wrapper}=await render(HomeResearchOverview,{historyState:{loading:false,error:true,items:[]}});expect(wrapper.text()).toContain('讀取失敗');overrides.delete('/api/workbench/projects');await button(wrapper,'重試').trigger('click');await tick();expect(wrapper.text()).toContain('測試研究');await button(wrapper,'查看紀錄與重試').trigger('click');expect(wrapper.emitted('history')).toHaveLength(1);expect(requests('/projects')).toHaveLength(2);expect(writes()).toHaveLength(0)})
})

