 it('saves a disabled sensitivity plan using named profiles, bounded repetitions and zero model calls',async()=>{overrides.set('/api/settings/profiles',()=>({profiles:[{id:'model1',name:'本機連線',model:'fixture'}]}));overrides.set('/api/workbench/projects/p/plans',c=>c.method==='post'?page([{plan_id:'plan',kind:body(c).kind,definition:body(c).definition}]):page([]));const {wrapper}=await render();await wrapper.findAll('button').find(b=>b.text()==='總覽').trigger('click');await tick();await button(wrapper,'已保存的更新與實驗計畫').trigger('click');await tick();await wrapper.get('#plan-kind').setValue('sensitivity');await tick();await wrapper.get('#plan-scope').setValue('同一來源比較');await wrapper.get('#plan-repeats').setValue(3);await wrapper.get('.plan-models input').setValue(true);await wrapper.get('.plan-form').trigger('submit');await tick();expect(body(writes()[0]).definition).toMatchObject({enabled:false,repeat_count:3,model_profile_ids:['model1'],budget:{max_attempts:0,max_model_calls:0}});expect(writes()).toHaveLength(1);expect(wrapper.text()).toContain('模型呼叫預算固定為 0')})
