 it('polls tasks only while visible, stops while settings hides the retained workspace, and never overlaps reads',async()=>{vi.useFakeTimers({toFake:['setTimeout','clearTimeout']});const visibility=vi.spyOn(document,'visibilityState','get').mockReturnValue('visible');const retained={components:{Workbench},template:'<Workbench />'};const {router}=await render(retained,{},'/workbench?view=tasks');expect(requests('/tasks')).toHaveLength(1);await vi.advanceTimersByTimeAsync(5000);await tick();expect(requests('/tasks')).toHaveLength(2);visibility.mockReturnValue('hidden');document.dispatchEvent(new Event('visibilitychange'));await vi.advanceTimersByTimeAsync(10000);expect(requests('/tasks')).toHaveLength(2);visibility.mockReturnValue('visible');document.dispatchEvent(new Event('visibilitychange'));await tick();expect(requests('/tasks')).toHaveLength(3);await router.push('/settings');await tick();await vi.advanceTimersByTimeAsync(10000);expect(requests('/tasks')).toHaveLength(3);await router.push('/workbench?view=tasks');await tick();expect(requests('/tasks')).toHaveLength(4);const delayed=deferred();overrides.set('/api/workbench/tasks',()=>delayed.promise);await vi.advanceTimersByTimeAsync(15000);expect(requests('/tasks')).toHaveLength(5);delayed.resolve({items:[],runs:[]});await tick();expect(writes()).toHaveLength(0)})
 it('shows only grounded nonzero progress and preserves both task errors and heartbeat metadata',async()=>{overrides.set('/api/workbench/tasks',()=>({items:[{task_id:'a',progress:0,status:'processing'},{task_id:'b',progress:40,status:'processing',progress_detail:{}},{task_id:'c',progress:40,status:'processing',progress_detail:{completed_units:2,total_units:5},heartbeat:'recent-heartbeat',updated_at:'updated-time',attempt_id:'attempt-fixture',message:'saved message',error:'saved error'},{task_id:'d',progress:100,status:'completed'}],runs:[]}));const {wrapper}=await render(Workbench,{},'/workbench?view=tasks');expect(wrapper.findAll('progress')).toHaveLength(2);expect(wrapper.text()).toContain('recent-heartbeat');expect(wrapper.text()).toContain('attempt-fixture');expect(wrapper.text()).toContain('saved message');expect(wrapper.text()).toContain('saved error');expect(wrapper.text()).toContain('2 / 5')})
 it('keeps research requests on the same origin and does not claim configured services have been exercised',()=>{expect(api.workbenchClient.defaults.baseURL).toBe('/');expect(zhTW.home.systemReady).toBe('連線設定已齊備');expect(zhTW.home.systemReadyDesc).toContain('尚需明確啟動與驗證')})
 it('shows observed counts with synthetic separation and exclusion reasons, never as accuracy',async()=>{overrides.set('/api/workbench/projects/p/quality',()=>({source_preservation:{value:null},citation_location:{value:null},run_counts:{total:3,completed:2,incomplete:1},repeat_stability:{status:'observed',sample_size:2,groups:[{group_id:'g',kind:'synthetic_fixture',sample_size:2,simulation_ids:['s1','s2'],kind_counts:{twitter:{POST:{min:2,max:5}}},models:[{run_id:'r',model:{provider:'none',model:'fixture'}}]}],excluded:[{simulation_id:'old',message:'缺少來源版本'}],limitations:['只有事件計數。']},model_sensitivity:{status:'not_evaluated',sample_size:0,groups:[]},assumptions:[],contradictions:[],limitations:[]}));const {wrapper}=await render();await button(wrapper,'結果').trigger('click');await tick();await button(wrapper,'品質與限制').trigger('click');await tick();expect(wrapper.text()).toContain('2 個可比較樣本');expect(wrapper.text()).toContain('合成示範');expect(wrapper.text()).toContain('缺少來源版本');expect(wrapper.text()).toContain('不代表準確率');expect(wrapper.findAll('.observed-quality table td').map(x=>x.text())).toContain('5');expect(writes()).toHaveLength(0)})
